import { createHash } from 'node:crypto';
import { and, eq, gt, gte, isNotNull, isNull } from 'drizzle-orm';
import type { GuildScope } from '../scope.js';
import { read, write } from '../write.js';
import { mcpBulkPreviews } from '../schema.js';

/**
 * Stored bulk role-change previews (slice 4, task 1): the durable half of
 * the preview → confirm handshake. Every function takes a `GuildScope`
 * first and scopes through `scope.only`, like every repository here.
 *
 * The confirm token is a random 128-bit value generated by the caller. The
 * table keeps only its sha256 hex (`token_hash`); `createPreview` hashes
 * what it is given and `findPreviewByToken` hashes its input, so the token
 * itself never reaches a row.
 */

export type McpBulkActionKind = 'add' | 'remove';

export interface McpBulkPreviewRow {
  readonly previewId: string;
  readonly actionKind: McpBulkActionKind;
  readonly roleId: string;
  readonly argsHash: string;
  readonly memberIds: readonly string[];
  readonly createdAt: number;
  readonly expiresAt: number;
  readonly consumedAt: number | undefined;
  readonly jobId: number | undefined;
}

const toPreviewRow = (row: typeof mcpBulkPreviews.$inferSelect): McpBulkPreviewRow => ({
  previewId: row.previewId,
  actionKind: row.actionKind as McpBulkActionKind,
  roleId: row.roleId,
  argsHash: row.argsHash,
  memberIds: JSON.parse(row.memberIdsJson) as readonly string[],
  createdAt: row.createdAt,
  expiresAt: row.expiresAt,
  consumedAt: row.consumedAt ?? undefined,
  jobId: row.jobId ?? undefined,
});

const hashToken = (token: string): string =>
  createHash('sha256').update(token, 'utf8').digest('hex');

/**
 * Stores the preview, keeping only the token's hash. A repeated preview id
 * or a repeated token throws — two previews never share a token hash.
 */
export const createPreview = (
  scope: GuildScope,
  input: {
    previewId: string;
    token: string;
    actionKind: McpBulkActionKind;
    roleId: string;
    argsHash: string;
    memberIds: readonly string[];
    createdAt: number;
    expiresAt: number;
  },
): void =>
  write(scope, ({ db }) => {
    db.insert(mcpBulkPreviews)
      .values({
        guildId: scope.guildId,
        previewId: input.previewId,
        tokenHash: hashToken(input.token),
        actionKind: input.actionKind,
        roleId: input.roleId,
        argsHash: input.argsHash,
        memberIdsJson: JSON.stringify([...input.memberIds]),
        createdAt: input.createdAt,
        expiresAt: input.expiresAt,
        consumedAt: null,
        jobId: null,
      })
      .run();
  });

/**
 * The preview holding this token in this guild, if any. Hashes the input.
 * Found is not valid: expired and consumed rows come back too, so a caller
 * reads `expiresAt`/`consumedAt` for its refusal text and acts only after
 * `consumePreview` succeeds — that predicated update is the single-use gate.
 */
export const findPreviewByToken = (
  scope: GuildScope,
  token: string,
): McpBulkPreviewRow | undefined =>
  read(scope, (db) => {
    const row = db
      .select()
      .from(mcpBulkPreviews)
      .where(scope.only(mcpBulkPreviews, eq(mcpBulkPreviews.tokenHash, hashToken(token))))
      .get();
    return row === undefined ? undefined : toPreviewRow(row);
  });

/**
 * The preview with this id in this guild, if any — the durable job's read
 * path. The job carries only the preview id (never the confirm token, which
 * must not sit in the durable jobs table), so it loads the stored member set
 * here and walks it from its persisted cursor, never re-resolving membership.
 * Consumed and expired rows come back too: the job decides those itself.
 */
export const findPreviewById = (
  scope: GuildScope,
  previewId: string,
): McpBulkPreviewRow | undefined =>
  read(scope, (db) => {
    const row = db
      .select()
      .from(mcpBulkPreviews)
      .where(scope.only(mcpBulkPreviews, eq(mcpBulkPreviews.previewId, previewId)))
      .get();
    return row === undefined ? undefined : toPreviewRow(row);
  });

/**
 * Single-use, expiring claim: sets `consumed_at` and `job_id` only when the
 * row is still unconsumed and `now` is before `expires_at`. The predicate
 * is in the UPDATE itself, so two concurrent confirms consume once.
 */
export const consumePreview = (
  scope: GuildScope,
  previewId: string,
  jobId: number,
  now: number,
): boolean =>
  write(scope, ({ db }) => {
    const result = db
      .update(mcpBulkPreviews)
      .set({ consumedAt: now, jobId })
      .where(
        scope.only(
          mcpBulkPreviews,
          and(
            eq(mcpBulkPreviews.previewId, previewId),
            isNull(mcpBulkPreviews.consumedAt),
            gt(mcpBulkPreviews.expiresAt, now),
          ),
        ),
      )
      .run();
    return result.changes === 1;
  });

/**
 * The `member_role` cap's bulk half (ADR 0118 §8, no migration): how many
 * previews this guild consumed since `sinceMs`, and the total members those
 * previews covered. The daemon's `countSince` subtracts the count (one
 * `role.bulk` ledger row per consumed preview — every confirm claims exactly
 * one row and consumes exactly one preview inside its execute) and adds the
 * member total, so the cap counts members instead of confirms.
 *
 * Bounds match `countActionsSince` (`consumed_at >= sinceMs`, like the
 * ledger's `created_at >= sinceMs`): a preview consumed microseconds after
 * its action row was claimed still lands in the same window except at the
 * exact boundary. Unconsumed rows — including dry-run confirms, whose execute
 * never runs — never count here.
 */
export interface ConsumedPreviewTotals {
  readonly previewCount: number;
  readonly memberTotal: number;
}

export const sumConsumedMembers = (
  scope: GuildScope,
  sinceMs: number,
): ConsumedPreviewTotals =>
  read(scope, (db) => {
    const rows = db
      .select({ memberIdsJson: mcpBulkPreviews.memberIdsJson })
      .from(mcpBulkPreviews)
      .where(
        scope.only(
          mcpBulkPreviews,
          and(isNotNull(mcpBulkPreviews.consumedAt), gte(mcpBulkPreviews.consumedAt, sinceMs)),
        ),
      )
      .all();
    let memberTotal = 0;
    for (const row of rows) {
      const ids = JSON.parse(row.memberIdsJson) as readonly unknown[];
      memberTotal += ids.length;
    }
    return { previewCount: rows.length, memberTotal };
  });
